import { useDocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) => {
	const doc = useDocAccess(docQuery(props.id));
	return <h1>{doc.title}</h1>;
};

import { Match, Result } from "effect";

import { useSession } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) =>
	Result.match(useSession(docQuery(props.id)), {
		onFailure: (error) =>
			Match.valueTags(error, {
				DocNotFound: () => <p>No such doc</p>,
			}),
		onSuccess: (doc) => <h1>{doc.title}</h1>,
	});

import { Match, Result } from "effect";

import { useDocAccess } from "../src/boundaries.tsx";
import { docQuery } from "../src/queries.ts";

export const Title = (props: { readonly id: number }) =>
	Result.match(useDocAccess(docQuery(props.id)), {
		onFailure: (error) =>
			Match.valueTags(error, {
				DocNotFound: () => <p>No such doc</p>,
				Unauthorized: () => <p>Sign in</p>,
			}),
		onSuccess: (doc) => <h1>{doc.title}</h1>,
	});

import { Boundary } from "@raf-query/experimental-effect-query";

import { Unauthorized } from "../src/api.ts";
import { DocAccess } from "../src/boundaries.tsx";

export const [Again, useAgain] = Boundary.catchErrors(DocAccess, {
	errors: [Unauthorized],
	fallback: () => <p>Sign in again</p>,
	name: "Again",
});

import { Effect } from "effect";
import { Query } from "@raf-query/experimental-effect-query";

import { Forbidden, Unauthorized } from "../src/api.ts";
import { DocsClient } from "../src/client.ts";

export const docQuery = (id: number) =>
	Query.make({
		effect: Effect.flatMap(DocsClient, (docs) => docs.GetDoc({ id })),
		errors: [Forbidden, Unauthorized],
		key: ["docs", id],
	});

import { Context, Effect } from "effect";
import { Query } from "@raf-query/experimental-effect-query";

import { useDocAccess } from "../src/boundaries.tsx";

class Analytics extends Context.Service<
	Analytics,
	{ readonly views: Effect.Effect<number> }
>()("Analytics") {}

const views = Query.make({
	effect: Effect.flatMap(Analytics, (analytics) => analytics.views),
	errors: [],
	key: ["views"],
});

export const Views = () => <p>{useDocAccess(views)} views</p>;

import { Boundary } from "@raf-query/experimental-effect-query";

import { DocNotFound } from "../src/api.ts";
import { DocAccess, useSession } from "../src/boundaries.tsx";
import { docList, docQuery } from "../src/queries.ts";

export const [Everything, useEverything] = Boundary.catchErrors(DocAccess, {
	errors: [DocNotFound],
	fallback: (props) => <p>Doc {props.error.docId} is gone</p>,
	name: "Everything",
});

export const Title = (props: { readonly id: number }) => {
	const doc = useEverything(docQuery(props.id));
	return <h1>{doc.title}</h1>;
};

export const Titles = () => {
	const docs = useSession(docList);
	return (
		<ul>
			{docs.map((doc) => (
				<li key={doc.id}>{doc.title}</li>
			))}
		</ul>
	);
};
